dashboard.definition:
{
  "title": "Wazuh - GDPR - Overview dashboard",
  "description": "GDPR - Overview dashboard of the Wazuh dashboard, on the findings exported from the Wazuh indexer.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "dataSources": {
    "ds_01": {
      "type": "ds.search",
      "name": "Top 10 agents by events number",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.gdpr{}\"=* | eval f1='wazuh.agent.name' | stats count as metric by f1 | sort - metric | head 10 | rename f1 as \"wazuh.agent.name\", metric as \"Count\""
      }
    },
    "ds_02": {
      "type": "ds.search",
      "name": "GDPR requirements",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.gdpr{}\"=* | eval f1='wazuh.rule.compliance.gdpr{}' | timechart useother=f usenull=f limit=10 count by f1"
      }
    },
    "ds_03": {
      "type": "ds.search",
      "name": "Top requirements over time",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.gdpr{}\"=* | eval f1='wazuh.rule.compliance.gdpr{}' | timechart useother=f usenull=f limit=5 count by f1"
      }
    },
    "ds_04": {
      "type": "ds.search",
      "name": "Last events",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.gdpr{}\"=* | eval f1='wazuh.rule.compliance.gdpr{}', f2='wazuh.agent.name' | stats count as metric by f1, f2 | sort - metric | head 25 | rename f1 as \"Requirements\", f2 as \"Agents\", metric as \"Count\""
      }
    },
    "ds_05": {
      "type": "ds.search",
      "name": "Requirements by agent",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.gdpr{}\"=* | eval f1='wazuh.rule.compliance.gdpr{}', f2='wazuh.agent.name' | chart count over f1 by f2 useother=f usenull=f limit=5 | addtotals fieldname=total | sort - total | head 5 | fields - total | rename f1 as \"GDPR Requirements\""
      }
    }
  },
  "visualizations": {
    "viz_01": {
      "type": "splunk.pie",
      "title": "Top 10 agents by events number",
      "dataSources": {
        "primary": "ds_01"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_02": {
      "type": "splunk.line",
      "title": "GDPR requirements",
      "dataSources": {
        "primary": "ds_02"
      },
      "options": {}
    },
    "viz_03": {
      "type": "splunk.area",
      "title": "Top requirements over time",
      "dataSources": {
        "primary": "ds_03"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_04": {
      "type": "splunk.punchcard",
      "title": "Last events",
      "dataSources": {
        "primary": "ds_04"
      },
      "options": {}
    },
    "viz_05": {
      "type": "splunk.column",
      "title": "Requirements by agent",
      "dataSources": {
        "primary": "ds_05"
      },
      "options": {
        "stackMode": "stacked"
      }
    }
  },
  "layout": {
    "type": "absolute",
    "options": {
      "width": 1200,
      "height": 1056,
      "display": "auto-scale"
    },
    "globalInputs": [
      "input_global_trp"
    ],
    "structure": [
      {
        "item": "viz_01",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 821,
          "h": 276
        }
      },
      {
        "item": "viz_02",
        "type": "block",
        "position": {
          "x": 825,
          "y": 0,
          "w": 371,
          "h": 276
        }
      },
      {
        "item": "viz_03",
        "type": "block",
        "position": {
          "x": 0,
          "y": 280,
          "w": 1196,
          "h": 216
        }
      },
      {
        "item": "viz_04",
        "type": "block",
        "position": {
          "x": 0,
          "y": 500,
          "w": 1196,
          "h": 376
        }
      },
      {
        "item": "viz_05",
        "type": "block",
        "position": {
          "x": 0,
          "y": 860,
          "w": 1196,
          "h": 176
        }
      }
    ]
  }
}
